from __future__ import annotations

from api.operator_console_dispatch_preview import CONSOLE_HTML_V35

DISPATCH_TICKET_SCRIPT = r"""
<style>
.ticket-panel{margin-top:14px;background:#fff;border:1px solid #dce9f8;border-radius:18px;padding:18px;box-shadow:0 12px 34px rgba(11,47,97,.05)}.ticket-form{display:grid;grid-template-columns:1fr 120px 120px;gap:10px}.ticket-form select,.ticket-form input,.ticket-form textarea{width:100%;border:1px solid #cbdced;border-radius:10px;padding:10px;font:inherit;background:#fff}.ticket-form textarea{grid-column:1/-1;min-height:80px;resize:vertical}.ticket-form button{grid-column:1/-1;border:0;border-radius:10px;padding:12px;background:#0b2f61;color:#fff;font-weight:800;cursor:pointer}.ticket-form button:disabled{opacity:.55;cursor:not-allowed}.ticket-warning{padding:12px;border:1px solid #f2dfb8;background:#fff8ea;border-radius:10px;color:#7c4b00;margin-bottom:10px}.ticket-status{min-height:20px;margin-top:10px;font-size:13px}.ticket-status.ok{color:#147a46}.ticket-status.err{color:#b42318}@media(max-width:700px){.ticket-form{grid-template-columns:1fr}.ticket-form textarea,.ticket-form button{grid-column:1}}
</style>
<script>
async function loadDispatchTicketControl(recordId){const view=document.getElementById('view');if(!view||!recordId)return;let box=document.getElementById('dispatch-ticket-control');if(!box){box=document.createElement('section');box.id='dispatch-ticket-control';box.className='ticket-panel';const timeline=view.querySelector('.timeline');if(timeline)view.insertBefore(box,timeline);else view.appendChild(box)}box.innerHTML='<h3>Prepare Single-Use Dispatch Ticket</h3><div class="muted">Checking current final authorization…</div>';try{const r=await fetch('/operator/api/cases/'+encodeURIComponent(recordId)+'/dispatch-context',{credentials:'same-origin'});if(r.status===401){location.href='/operator/login';return}if(!r.ok){const x=await r.json().catch(()=>({}));throw new Error(x.detail||'dispatch context unavailable')}const d=await r.json();if(!d.ready){box.innerHTML=`<h3>Prepare Single-Use Dispatch Ticket</h3><div class="muted">Not available: ${esc((d.reason||'not ready').replaceAll('_',' '))}</div>`;return}const ops=(d.dispatch_contract.allowed_operations||[]).map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');box.innerHTML=`<h3>Prepare Single-Use Dispatch Ticket</h3><div class="ticket-warning">A ticket freezes one exact read-only operation. It is short-lived and single-use. Preparing it does <strong>not</strong> run it. A newer ticket under the same final authorization makes an older unconsumed ticket stale.</div><form id="ticket-form" class="ticket-form"><select id="ticket-op">${ops}</select><input id="ticket-limit" type="number" min="1" max="20" value="5" title="Result limit"><input id="ticket-ttl" type="number" min="1" max="5" value="3" title="Ticket TTL minutes"><textarea id="ticket-purpose" placeholder="Purpose for this exact read-only dispatch"></textarea><button id="ticket-submit">Prepare dispatch ticket</button></form><div id="ticket-status" class="ticket-status"></div>`;box.querySelector('#ticket-form').addEventListener('submit',async(e)=>{e.preventDefault();const status=box.querySelector('#ticket-status');const btn=box.querySelector('#ticket-submit');status.textContent='';status.className='ticket-status';btn.disabled=true;try{const csrf=await loadConsoleCsrf();const body={operation:box.querySelector('#ticket-op').value,limit:Number(box.querySelector('#ticket-limit').value||5),purpose:box.querySelector('#ticket-purpose').value,ttl_minutes:Number(box.querySelector('#ticket-ttl').value||3)};const rr=await fetch('/operator/api/execution-authorizations/'+encodeURIComponent(d.execution_authorization_id)+'/dispatch-ticket',{method:'POST',headers:{'content-type':'application/json','x-vmi-csrf':csrf},credentials:'same-origin',body:JSON.stringify(body)});if(!rr.ok){const x=await rr.json().catch(()=>({}));throw new Error(x.detail||'Dispatch ticket rejected')}const x=await rr.json();status.textContent=`Ticket ${x.ticket.dispatch_ticket_id} prepared for ${x.ticket.operation}. Nothing has run yet.`;status.className='ticket-status ok';setTimeout(()=>loadCase(recordId),300)}catch(err){status.textContent=String(err.message||err);status.className='ticket-status err'}finally{btn.disabled=false}})}catch(err){box.innerHTML=`<h3>Prepare Single-Use Dispatch Ticket</h3><div class="muted">${esc(err.message||'Unavailable.')}</div>`}}
const _v35LoadCase=loadCase;loadCase=async function(id){await _v35LoadCase(id);await loadDispatchTicketControl(id)};setTimeout(()=>{if(selected)loadDispatchTicketControl(selected)},1600);
</script>
"""

CONSOLE_HTML_V37 = CONSOLE_HTML_V35.replace("</body>", DISPATCH_TICKET_SCRIPT + "</body>")
